      const it = q.items[qi]; locked = false; stable = null; qCard.className = 'finger-q'; qCard.firstChild.textContent = `Question ${qi + 1} of ${q.items.length}`; qCard.lastChild.textContent = /\?$/.test(it.t) ? it.t : `${it.t} = ?`;
